<?php
declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; methodOnly('GET'); safeApi(function():void{$db=apiDatabase();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$sql=$id?'SELECT c.*,COUNT(sc.id) sub_category_count FROM categories c LEFT JOIN sub_categories sc ON sc.category_id=c.id WHERE c.id=:id GROUP BY c.id':'SELECT c.*,COUNT(sc.id) sub_category_count FROM categories c LEFT JOIN sub_categories sc ON sc.category_id=c.id GROUP BY c.id ORDER BY c.sort_order,c.name';$s=$db->prepare($sql);$s->execute($id?[':id'=>$id]:[]);$d=$id?$s->fetch():$s->fetchAll();if($id&&!$d)jsonResponse(false,'Category not found.',null,[],404);jsonResponse(true,'Categories loaded.',$d);});
